codify_input_html = """
<style>
/* Transform the Streamlit Text Area into a deeply recessed 3D interface */
div.stTextArea > div {
    background: linear-gradient(180deg, rgba(2, 4, 10, 0.95) 0%, rgba(10, 15, 30, 0.8) 100%) !important;
    border-top: 8px solid #00e5ff !important;
    border-left: 2px solid rgba(0, 229, 255, 0.3) !important;
    border-right: 2px solid rgba(0, 229, 255, 0.3) !important;
    border-bottom: 2px solid rgba(0, 229, 255, 0.1) !important;
    border-radius: 12px;
    box-shadow: inset 0 40px 60px rgba(0,0,0,1), 0 10px 30px rgba(0,229,255,0.15) !important;
    transform-style: preserve-3d;
    transform: perspective(800px) rotateX(1deg);
    transition: all 0.3s ease-in-out;
    position: relative;
    z-index: 1;
}

/* Ensure the text box wrapper itself allows the overlapping elements */
div.stTextArea {
    position: relative;
    z-index: 10;
}

/* Allow user to safely type without clicking the mascot */
textarea {
    position: relative;
    z-index: 5;
    padding-top: 30px !important;
    padding-right: 120px !important;
    color: #00e5ff !important;
    text-shadow: 0 0 5px rgba(0,229,255,0.3);
}

/* High-tech glass glare spanning the top edge */
div.stTextArea > div::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 15px;
    background: linear-gradient(180deg, rgba(255,255,255,0.2) 0%, transparent 100%);
    pointer-events: none;
}

/* Animation of the mascot peering into the 'well' */
@keyframes peek-into-well {
    0%, 100% { transform: rotateX(0deg) translateY(0); filter: drop-shadow(0 25px 25px rgba(0,0,0,0.8)); }
    50% { transform: rotateX(10deg) translateY(8px); filter: drop-shadow(0 15px 15px rgba(0,0,0,0.95)); }
}
</style>

<!-- Mascot overlay container that places it directly ON the input box's top-right brim, dangling inward -->
<div style="position: relative; width: 100%; height: 0; z-index: 9999; pointer-events: none;">
<img src="data:image/png;base64," style="position: absolute; right: 25px; top: -40px; width: 160px; height: auto; transform-origin: top center; animation: peek-into-well 4s ease-in-out infinite; pointer-events: none;" />
</div>
"""
